// 闭区间 [lo, hi]：里面若有 target 就一直留在区间内。退出时 lo = hi + 1。
// 适用于 704 这种元素互异、命中任意下标即可的查找。
// 有重复又要最左位置时改用 lowerBound，不能在相等时立刻返回。
static int binarySearch(int[] nums, int target) {
    int lo = 0, hi = nums.length - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2; // 避免 lo + hi 溢出
        if (nums[mid] == target) return mid;
        if (nums[mid] < target) lo = mid + 1;
        else hi = mid - 1;
    }
    return -1;
}

// 第一个 >= target 的下标。全部小于 target 时返回 nums.length（35 的插入点）。
// 闭区间写法：nums[mid] < target 才丢掉左半，相等时继续向左收。
static int lowerBound(int[] nums, int target) {
    int lo = 0, hi = nums.length - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (nums[mid] < target) lo = mid + 1;
        else hi = mid - 1;
    }
    return lo;
}

// 第一个 > target 的下标。最后一个 <= target 的下标是 upperBound(target) - 1。
static int upperBound(int[] nums, int target) {
    int lo = 0, hi = nums.length - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (nums[mid] <= target) lo = mid + 1;
        else hi = mid - 1;
    }
    return lo;
}

// LC 34：存在则返回首末下标，否则 [-1, -1]。35 直接返回 lowerBound。
static int[] searchRange(int[] nums, int target) {
    int l = lowerBound(nums, target);
    if (l == nums.length || nums[l] != target) return new int[]{-1, -1};
    return new int[]{l, upperBound(nums, target) - 1};
}

