// LC 33：元素互异。nums[lo] <= nums[mid] 时左半（含 mid）有序。
// target 落在这段有序区间里就丢掉另一半，否则丢掉这段。
// LC 81 有重复：若 nums[lo]、nums[mid]、nums[hi] 三者相等，有序半边无法判定，只做 lo++ 或 hi--，最坏退化为 O(n)。
static int searchRotated(int[] nums, int target) {
    int lo = 0, hi = nums.length - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (nums[mid] == target) return mid;
        if (nums[lo] <= nums[mid]) {
            if (nums[lo] <= target && target < nums[mid]) hi = mid - 1;
            else lo = mid + 1;
        } else {
            if (nums[mid] < target && target <= nums[hi]) lo = mid + 1;
            else hi = mid - 1;
        }
    }
    return -1;
}

// LC 1482：bloomDay[i] 为该花开放日，要用 k 朵相邻且已开放的花做一束，做 m 束。
// 不变量：[lo, hi] 含最小可行天数，hi 始终可行（最大开放日时花已全部开放）。
// 因此用 lo < hi，可行则 hi = mid，不可行则 lo = mid + 1，结束时 lo == hi。
// 换题改三处：上下界、canMake、收缩方向。
// 改成最大化最小值（最后一个可行值）时：mid = lo + (hi - lo + 1) / 2，可行则 lo = mid，否则 hi = mid - 1。
static int minDays(int[] bloomDay, int m, int k) {
    if ((long) m * k > bloomDay.length) return -1;
    int lo = Integer.MAX_VALUE, hi = Integer.MIN_VALUE;
    for (int day : bloomDay) {
        lo = Math.min(lo, day);
        hi = Math.max(hi, day);
    }
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (canMake(bloomDay, m, k, mid)) hi = mid;
        else lo = mid + 1;
    }
    return lo;
}

// day 这天能做成的花束数是否不少于 m。相邻已开放的花每凑满 k 朵算一束。
static boolean canMake(int[] bloomDay, int m, int k, int day) {
    int bouquets = 0, streak = 0;
    for (int bloom : bloomDay) {
        if (bloom <= day) {
            if (++streak == k) {
                bouquets++;
                streak = 0;
            }
        } else {
            streak = 0;
        }
    }
    return bouquets >= m;
}

