import java.util.*;

class Solution {
    public int search(int[] nums, int target) {
        int left = 0;
        int right = nums.length - 1; // 闭区间右端是最后一个下标。

        while (left <= right) {
            int mid = left + (right - left) / 2;

            if (nums[mid] == target) {
                return mid;
            }

            if (nums[mid] < target) {
                left = mid + 1; // 左半及中点都更小，丢掉。
            } else {
                right = mid - 1; // 右半及中点都更大，丢掉。
            }
        }

        return -1;
    }
}

import java.util.*; // 本解法只用到数组下标，保留题目给出的导入。

class Solution {
    public int searchInsert(int[] nums, int target) {
        // 右端不包含，循环结束时 left 就是第一个 >= target 的下标。
        int left = 0;
        int right = nums.length;

        while (left < right) {
            int middle = left + (right - left) / 2;

            if (nums[middle] < target) {
                // middle 比目标小，它和左边都不可能是插入点。
                left = middle + 1;
            } else {
                // middle 仍可能是第一个 >= target 的位置，不能划出去。
                right = middle;
            }
        }
        return left;
    }
}

import java.util.*;

class Solution {
    public int[] searchRange(int[] nums, int target) {
        // 左边界：第一个 >= target 的下标。
        int first = lowerBound(nums, target);
        if (first == nums.length || nums[first] != target) {
            return new int[]{-1, -1};
        }

        // 右开端减一即最后一次出现，不必计算 target + 1。
        int last = upperBound(nums, target) - 1;
        return new int[]{first, last};
    }

    // 右端取 length，停在第一个不小于 target 的位置。
    private int lowerBound(int[] nums, int target) {
        int left = 0, right = nums.length;
        while (left < right) {
            int mid = left + (right - left) / 2;
            // 更小才丢掉左半，否则 mid 仍可能是答案。
            if (nums[mid] < target) left = mid + 1;
            else right = mid;
        }
        return left;
    }

    // 条件改成 <=，停在第一个大于 target 的位置。
    private int upperBound(int[] nums, int target) {
        int left = 0, right = nums.length;
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (nums[mid] <= target) left = mid + 1;
            else right = mid;
        }
        return left;
    }
}

import java.util.*; // Java 常用集合、队列、堆与数组工具

class Solution {
    public int search(int[] nums, int target) {
        int left = 0, right = nums.length - 1;

        while (left <= right) {
            int middle = left + (right - left) / 2;
            if (nums[middle] == target) return middle;

            // 旋转后二分，至少有一半仍然完全有序。
            if (nums[left] <= nums[middle]) {
                // 左半有序，看 target 是否落在 [nums[left], nums[middle])。
                if (nums[left] <= target && target < nums[middle]) {
                    right = middle - 1;
                } else {
                    left = middle + 1;
                }
            } else {
                // 右半有序，看 target 是否落在 (nums[middle], nums[right]]。
                if (nums[middle] < target && target <= nums[right]) {
                    left = middle + 1;
                } else {
                    right = middle - 1;
                }
            }
        }
        return -1;
    }
}

import java.util.*; // Java 常用集合、队列、堆与数组工具

class Solution {
    public int findMin(int[] nums) {
        int left = 0, right = nums.length - 1;

        while (left < right) {
            int middle = left + (right - left) / 2;

            if (nums[middle] > nums[right]) {
                // 中点在大值区，最小值一定在 middle 右边。
                left = middle + 1;
            } else {
                // middle 可能就是最小值，所以 right 收到 middle。
                right = middle;
            }
        }
        return nums[left];
    }
}

class Solution {
    public boolean search(int[] nums, int target) {
        int left = 0;
        int right = nums.length - 1;

        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (nums[mid] == target) return true;

            // 两端和 mid 同值时分不出哪边有序，只能同时丢掉两端。
            if (nums[left] == nums[mid] && nums[mid] == nums[right]) {
                left++;
                right--;
                continue;
            }

            if (nums[left] <= nums[mid]) {
                // 左半有序，target 在这段里才向左收，否则去右半。
                if (nums[left] <= target && target < nums[mid]) {
                    right = mid - 1;
                } else {
                    left = mid + 1;
                }
            } else {
                // 右半有序，同理只在这段内才向右收。
                if (nums[mid] < target && target <= nums[right]) {
                    left = mid + 1;
                } else {
                    right = mid - 1;
                }
            }
        }

        return false;
    }
}

import java.util.*;

class Solution {
    public int mySqrt(int x) {
        int left = 0;
        int right = x;
        int answer = 0;

        while (left <= right) {
            int mid = left + (right - left) / 2;
            long square = (long) mid * mid; // 用 long 避免 mid * mid 溢出。

            if (square <= x) {
                answer = mid;      // 当前 mid 可行，先记下。
                left = mid + 1;    // 继续找更大的可行值。
            } else {
                right = mid - 1;
            }
        }

        return answer;
    }
}

class Solution {
    public int preimageSizeFZF(int k) {
        // 等于 k 的区间长度 = 第一次达到 k+1 的位置 − 第一次达到 k 的位置
        return (int) (leftBound(k + 1) - leftBound(k));
    }

    private long leftBound(int k) {
        long left = 0, right = 5L * (k + 1);
        while (left < right) {
            long mid = left + ((right - left) >>> 1);
            if (trailingZeroes(mid) >= k) {
                right = mid; // 末尾零已经不少于 k，答案在左半边（含 mid）
            } else {
                left = mid + 1;
            }
        }
        return left;
    }

    private long trailingZeroes(long n) {
        long ans = 0;
        while (n > 0) {
            n /= 5;
            ans += n; // 每多除一次 5，累加这一层贡献的因子 5
        }
        return ans;
    }
}

class Solution {
    public int minDays(int[] bloomDay, int m, int k) {
        // 花不够凑成 m 束，不可能
        if ((long) m * k > bloomDay.length) {
            return -1;
        }
        int left = 1, right = 0;
        for (int day : bloomDay) {
            right = Math.max(right, day);
        }
        while (left < right) {
            int mid = left + (right - left) / 2;
            // 能做成就尝试更少天数，否则必须再等
            if (canMake(bloomDay, m, k, mid)) {
                right = mid;
            } else {
                left = mid + 1;
            }
        }
        return left;
    }

    private boolean canMake(int[] bloomDay, int m, int k, int limit) {
        int flowers = 0, bouquets = 0;
        for (int day : bloomDay) {
            if (day <= limit) {
                flowers++;
                // 相邻 k 朵才算一束，凑满后重新开始计数
                if (flowers == k) {
                    bouquets++;
                    flowers = 0;
                }
            } else {
                flowers = 0;
            }
        }
        return bouquets >= m;
    }
}

public class MaximizeMinMexAfterPartition {
    public int maximizeMinMex(int[] nums, int k) {
        int n = nums.length;

        // 每段至少要容纳 0..x-1 共 x 个数，x 不超过 n/k
        int left = 0;
        int right = n / k;
        int ans = 0;

        while (left <= right) {
            int mid = left + ((right - left) >> 1);
            if (canSplit(nums, k, mid)) {
                // 当前 MEX 可行，尝试更大的答案
                ans = mid;
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }

        return ans;
    }

    private boolean canSplit(int[] nums, int k, int targetMex) {
        if (targetMex == 0) {
            return true;
        }

        // seen[v] 等于 round 表示 v 在当前这一段已经出现
        int[] seen = new int[targetMex];
        int round = 1;
        int collected = 0;
        int segments = 0;

        for (int num : nums) {
            // 只有 0 到 targetMex-1 决定这一段能不能达到目标 MEX
            if (num >= 0 && num < targetMex && seen[num] != round) {
                seen[num] = round;
                collected++;
            }

            // 收齐就马上切段，后面还能继续凑段
            if (collected == targetMex) {
                segments++;
                if (segments >= k) {
                    return true;
                }

                round++;
                collected = 0;
            }
        }

        return false;
    }
}

import java.util.*;

class Solution {
    public boolean searchMatrix(int[][] matrix, int target) {
        if (matrix == null || matrix.length == 0
                || matrix[0] == null || matrix[0].length == 0) {
            return false;
        }

        int rows = matrix.length;
        int cols = matrix[0].length;

        // 用 long 存一维下标，避免 rows 与 cols 相乘时 int 溢出。
        long left = 0;
        long right = (long) rows * cols - 1;

        while (left <= right) {
            long mid = left + (right - left) / 2;
            int row = (int) (mid / cols);
            int col = (int) (mid % cols);
            int value = matrix[row][col];

            if (value == target) return true;
            if (value < target) left = mid + 1;
            else right = mid - 1;
        }
        return false;
    }
}

class Solution {
    public int kthSmallest(int[][] matrix, int k) {
        int n = matrix.length;
        // 第 k 小的值一定落在矩阵最小元和最大元之间。
        int left = matrix[0][0];
        int right = matrix[n - 1][n - 1];

        while (left < right) {
            int mid = (int) ((long) left + ((long) right - left) / 2);
            int count = countLessOrEqual(matrix, mid);

            // 不足 k 个则答案比 mid 大；否则 mid 仍可能就是答案。
            if (count < k) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }

        return left;
    }

    private int countLessOrEqual(int[][] matrix, int target) {
        int n = matrix.length;
        int row = n - 1;
        int col = 0;
        int count = 0;

        // 从左下角走：当前格不大于 target 时，同列上方全部计入。
        while (row >= 0 && col < n) {
            if (matrix[row][col] <= target) {
                count += row + 1;
                col++;
            } else {
                row--;
            }
        }

        return count;
    }
}

import java.util.*; // Java 常用集合、队列、堆与数组工具

class Solution {
    public double findMedianSortedArrays(int[] nums1, int[] nums2) {
        // 只在更短的数组上二分。
        if (nums1.length > nums2.length) {
            return findMedianSortedArrays(nums2, nums1);
        }

        int m = nums1.length;
        int n = nums2.length;
        int leftSize = (m + n + 1) / 2;
        int left = 0, right = m;

        while (left <= right) {
            int cut1 = left + (right - left) / 2;
            int cut2 = leftSize - cut1;

            // 切在端点外时用极值占位，避免下标越界。
            int left1 = (cut1 == 0) ? Integer.MIN_VALUE : nums1[cut1 - 1];
            int right1 = (cut1 == m) ? Integer.MAX_VALUE : nums1[cut1];
            int left2 = (cut2 == 0) ? Integer.MIN_VALUE : nums2[cut2 - 1];
            int right2 = (cut2 == n) ? Integer.MAX_VALUE : nums2[cut2];

            // 左半全部不超过右半，四个边界就能算出中位数。
            if (left1 <= right2 && left2 <= right1) {
                if ((m + n) % 2 == 1) {
                    return Math.max(left1, left2);
                }
                return ((double) Math.max(left1, left2)
                        + Math.min(right1, right2)) / 2.0;
            }

            if (left1 > right2) {
                right = cut1 - 1; // nums1 左边取多了。
            } else {
                left = cut1 + 1;  // nums1 左边取少了。
            }
        }

        throw new IllegalArgumentException("Input arrays must be sorted.");
    }
}

class Solution {
    public int findPeakElement(int[] nums) {
        int left = 0;
        int right = nums.length - 1;

        while (left < right) {
            // left < right 时 mid+1 一定还在区间里，可以和右侧比较。
            int mid = left + (right - left) / 2;

            if (nums[mid] < nums[mid + 1]) {
                // 右边更高，峰值不会停在 mid，收到 mid+1。
                left = mid + 1;
            } else {
                // 从 mid 开始不升，峰值就在 mid 或更左。
                right = mid;
            }
        }

        return left;
    }
}

class Solution {
    public int singleNonDuplicate(int[] nums) {
        int left = 0;
        int right = nums.length - 1;

        while (left < right) {
            int mid = left + (right - left) / 2;

            // 奇数下标是一对里的第二个，退回偶数才能和后一个比较。
            if ((mid & 1) == 1) mid--;

            if (nums[mid] == nums[mid + 1]) {
                // 这一对还没被拆开，单一元素只可能在 mid 右侧。
                left = mid + 2;
            } else {
                // 配对已经错位，答案就是 mid 或在它左边。
                right = mid;
            }
        }

        return nums[left];
    }
}
